package com.mediassistrover.backend.service.impl;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.mediassistrover.backend.dto.verification.request.QrVerificationRequests.Issue;
import com.mediassistrover.backend.dto.verification.response.*;
import com.mediassistrover.backend.entity.*;
import com.mediassistrover.backend.enums.*;
import com.mediassistrover.backend.exception.*;
import com.mediassistrover.backend.repository.*;
import com.mediassistrover.backend.security.AccountPrincipal;
import com.mediassistrover.backend.service.*;
import com.mediassistrover.backend.validation.RuntimeAuthorizationPolicy;
import com.mediassistrover.backend.validation.StaffOperationalScopePolicy;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.time.*;
import java.util.*;

@Service @RequiredArgsConstructor
public class QrVerificationServiceImpl implements QrVerificationService {
    private final QrChallengeRepository challengeRepository; private final AuthVerificationRepository verificationRepository;
    private final JobRepository jobRepository; private final JobStepRepository stepRepository; private final AccountRepository accountRepository;
    private final RuntimeStepCompletionService completionService; private final AuditService auditService; private final ObjectMapper objectMapper; private final Clock clock;
    private final StaffOperationalScopePolicy staffScope;
    private final SecureRandom random=new SecureRandom();
    @Override @Transactional public QrChallengeResponse issue(UUID jobId,Issue r,AccountPrincipal actor,RequestMetadata md){Job job=jobRepository.lockById(jobId).orElseThrow(()->new ResourceNotFoundException("Job not found: "+jobId));staffScope.requireJobAccess(job,actor);requireActor(actor);RuntimeAuthorizationPolicy.requireRunning(job);JobStep step=stepRepository.lockById(r.authJobStepId()).orElseThrow(()->new ResourceNotFoundException("JobStep not found"));if(!step.getJobTask().getJob().getJobId().equals(jobId)||step.getStep().getStepType()!=StepType.AUTHENTICATE||step.getStatus()!=JobStepStatus.RUNNING)throw new BusinessRuleException("QR challenge requires the RUNNING AUTHENTICATE Step in this Job");requireLiveAuthentication(job,step);if(r.validForSeconds()<30||r.validForSeconds()>300)throw new BusinessRuleException("QR validity must be 30-300 seconds");if(RuntimeAuthorizationPolicy.purpose(step)!=r.purpose())throw new BusinessRuleException("QR purpose does not match Step configuration");if(challengeRepository.findByAuthJobStepJobStepId(step.getJobStepId()).isPresent())throw new ConflictException("QR challenge already issued for this Step");byte[] bytes=new byte[32];random.nextBytes(bytes);String proof=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);Instant now=Instant.now(clock).truncatedTo(java.time.temporal.ChronoUnit.MICROS);QrChallenge c=challengeRepository.save(QrChallenge.builder().job(job).authJobStep(step).purpose(r.purpose()).tokenHash(hash(proof)).issuedAt(now).expiresAt(now.plusSeconds(r.validForSeconds())).build());auditService.record(accountRepository.findById(actor.accountId()).orElseThrow(),"QR_CHALLENGE_ISSUED","QrChallenge",c.getChallengeId(),null,Map.of("jobId",jobId,"purpose",r.purpose()),md);return new QrChallengeResponse(c.getChallengeId(),jobId,step.getJobStepId(),c.getPurpose(),proof,c.getExpiresAt());}
    @Override @Transactional public AuthVerificationResponse verify(UUID jobId,String proof,AccountPrincipal actor,RequestMetadata md){if(proof==null||proof.isBlank())throw new BusinessRuleException("QR proof is required");Job job=jobRepository.lockById(jobId).orElseThrow(()->new BusinessRuleException("QR proof is outside this Job"));staffScope.requireJobAccess(job,actor);requireActor(actor);RuntimeAuthorizationPolicy.requireRunning(job);QrChallenge c=challengeRepository.lockByTokenHash(hash(proof)).orElseThrow(()->new BusinessRuleException("QR proof is invalid"));if(!c.getJob().getJobId().equals(jobId))throw new BusinessRuleException("QR proof is outside this Job");Instant now=Instant.now(clock).truncatedTo(java.time.temporal.ChronoUnit.MICROS);if(c.getUsedAt()!=null)throw new ConflictException("QR proof has already been used");if(!c.getExpiresAt().isAfter(now))throw new BusinessRuleException("QR proof has expired");JobStep step=c.getAuthJobStep();requireLiveAuthentication(job,step);if(step.getStatus()!=JobStepStatus.RUNNING)throw new BusinessRuleException("Authentication Step is no longer awaiting proof");Account account=accountRepository.findById(actor.accountId()).orElseThrow();c.setUsedAt(now);c.setUsedByAccount(account);AuthVerification v=verificationRepository.save(AuthVerification.builder().job(job).authJobStep(step).actorAccount(account).actorTokenVersion(account.getTokenVersion()).method(AuthVerificationMethod.QR_CODE).purpose(c.getPurpose()).requiredPermission(c.getPurpose()==AuthVerificationPurpose.DELIVERY_SENDER?"DELIVERY_SEND":"DELIVERY_RECEIVE").issuedAt(now).validUntil(c.getExpiresAt()).build());var result=objectMapper.createObjectNode().put("authenticated",true).put("verified",true).put("verification_id",v.getVerificationId().toString()).put("actor_user_id",account.getAccountId().toString()).put("valid_until",v.getValidUntil().toString()).put("purpose",v.getPurpose().name());if(job.getSchemaVersion()==3) result=objectMapper.createObjectNode().put("verified",true).put("verification_id",v.getVerificationId().toString()).put("actor_account_id",account.getAccountId().toString()).put("valid_until",v.getValidUntil().toString()).put("purpose",v.getPurpose().name()).put("service_request_id",job.getServiceRequest().getServiceRequestId().toString()).put("verified_at",now.toString());completionService.complete(step,result,account,actor.role()==Role.ADMIN?JobEventProducerType.ADMIN:JobEventProducerType.STAFF,"QR_VERIFICATION_SUCCEEDED",null);auditService.record(account,"QR_PROOF_VERIFIED","AuthVerification",v.getVerificationId(),null,Map.of("jobId",jobId,"challengeId",c.getChallengeId()),md);return response(v);}
    private void requireActor(AccountPrincipal actor){Account account=accountRepository.findById(actor.accountId()).orElseThrow();if(account.getStatus()!=AccountStatus.ACTIVE||account.getRole()!=actor.role()||account.isMustChangePassword()||account.getTokenVersion()!=actor.tokenVersion())throw new org.springframework.security.access.AccessDeniedException("Active, unrestricted Staff/Admin session required");}
    private void requireLiveAuthentication(Job job,JobStep step){if(step.getStep().getParamsJson().has("method")&&!"QR_CODE".equals(step.getStep().getParamsJson().path("method").asText()))throw new BusinessRuleException("Authentication method does not match Step configuration");Instant now=Instant.now(clock);if(job.isBeOrchestrated()&&(job.getCancelRequestedAt()!=null||job.getSelectedJobStep()==null||!job.getSelectedJobStep().getJobStepId().equals(step.getJobStepId())||step.getStatus()!=JobStepStatus.RUNNING||step.getStartedAt()==null||!step.getStartedAt().plusSeconds(step.getTimeoutSecSnapshot()).isAfter(now)||job.getStartedAt()==null||!job.getStartedAt().plusSeconds(job.getWorkflow().getMaxDurationSec()).isAfter(now)))throw new BusinessRuleException("QR requires the selected, unexpired AUTHENTICATE step");}
    private String hash(String value){try{byte[] digest=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));return HexFormat.of().formatHex(digest);}catch(NoSuchAlgorithmException ex){throw new IllegalStateException(ex);}}
    private AuthVerificationResponse response(AuthVerification v){return new AuthVerificationResponse(v.getVerificationId(),v.getJob().getJobId(),v.getAuthJobStep().getJobStepId(),v.getActorAccount().getAccountId(),null,v.getMethod(),v.getPurpose(),v.getRequiredPermission(),v.getIssuedAt(),v.getValidUntil(),v.getRevokedAt());}
}
